import{_ as i,o as t,c as e,a2 as l}from"./chunks/framework.BXA5Pi9t.js";const g=JSON.parse('{"title":"Optimizing RGW Object Storage Mixed Media through Storage Classes and Lua Scripting","description":"","frontmatter":{"title":"Optimizing RGW Object Storage Mixed Media through Storage Classes and Lua Scripting","date":"2022-11-10T00:00:00.000Z","updated":"2022-11-11T00:00:00.000Z","tags":["Ceph","Distributed Storage","RGW Optimization","Lua Scripting","Storage Class"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2022/Optimizing_RGW_Object_Storage_Mixed_Media_through_Storage_Classes_and_Lua_Scripting.md","filePath":"posts/2022/Optimizing_RGW_Object_Storage_Mixed_Media_through_Storage_Classes_and_Lua_Scripting.md","lastUpdated":1780459816000}'),r={name:"posts/2022/Optimizing_RGW_Object_Storage_Mixed_Media_through_Storage_Classes_and_Lua_Scripting.md"};function o(n,a,s,u,_,d){return t(),e("div",null,[...a[0]||(a[0]=[l('<p>原总结准确反映了会议的关键细节，包括讨论的主要议题、决定的事项和后续行动计划。以下是对总结的改进，以增强其准确性和清晰度：</p><h3 id="改进后的会议纪要" tabindex="-1">改进后的会议纪要 <a class="header-anchor" href="#改进后的会议纪要" aria-label="Permalink to &quot;改进后的会议纪要&quot;">​</a></h3><h4 id="会议主题" tabindex="-1">会议主题 <a class="header-anchor" href="#会议主题" aria-label="Permalink to &quot;会议主题&quot;">​</a></h4><p>通过存储类和 Lua 脚本优化 RADOS Gateway 对象存储在混合媒体上的性能</p><h4 id="主讲人" tabindex="-1">主讲人 <a class="header-anchor" href="#主讲人" aria-label="Permalink to &quot;主讲人&quot;">​</a></h4><ul><li><strong>Kurt Bruns</strong>：Solidime 的软件工程师，SPDK 项目的贡献者。</li><li><strong>Anthony Diatri</strong>：Index Exchange 的首席工程师，著有《Seth Learning Seth》第二版，并参与 stuff 项目的文档编写。</li></ul><h4 id="会议内容" tabindex="-1">会议内容 <a class="header-anchor" href="#会议内容" aria-label="Permalink to &quot;会议内容&quot;">​</a></h4><ol><li><p><strong>背景介绍</strong></p><ul><li>RADOS Gateway (RGW) 的特点：对象大小多样，读取密集型工作负载（80% 读取，20% 写入），适用于 AI 工作负载。</li><li>小对象需要高 IOPS 和低延迟，大对象需要高读取吞吐量和带宽。</li></ul></li><li><p><strong>存储挑战</strong></p><ul><li>传统 HDD 性能有限，SSD 成本高，如何有效使用 SSD 是关键问题。</li></ul></li><li><p><strong>优化策略</strong></p><ul><li>使用存储类和 Lua 脚本优化 RGW 对象存储。</li><li>通过 S3 协议的存储类功能，将对象引导到不同的存储池。</li></ul></li><li><p><strong>技术细节</strong></p><ul><li>Blue Store 的 Min Alloc 大小为 4K，SSD 的 Indirection Unit 为 64K，可能导致空间放大。</li><li>Lua 脚本在对象上传时检查存储类，并根据对象大小自动分配到合适的存储池。</li></ul></li><li><p><strong>实施细节</strong></p><ul><li>Quincy 版本中引入自动调整 OSD 的 Min Alloc 大小为 SSD 的最佳 I/O 大小。</li><li>Lua 脚本修改存储类头部，动态调整存储类。</li></ul></li><li><p><strong>结果展示</strong></p><ul><li>Lua 脚本简化了对象存储的路由，提高存储效率。</li><li>示例展示了如何使用 Lua 脚本自动将对象存储到 TLC 和 QLC 池中。</li></ul></li></ol><h4 id="后续行动计划" tabindex="-1">后续行动计划 <a class="header-anchor" href="#后续行动计划" aria-label="Permalink to &quot;后续行动计划&quot;">​</a></h4><ul><li>继续优化和扩展 Lua 脚本功能，支持更多自定义存储策略。</li><li>监控和评估优化后的存储性能。</li></ul><h4 id="参考资料" tabindex="-1">参考资料 <a class="header-anchor" href="#参考资料" aria-label="Permalink to &quot;参考资料&quot;">​</a></h4><ul><li>相关论文和演示文稿的链接。</li><li>RADOS Gateway Lua 脚本文档和示例。</li><li>空间放大表和 TCO 计算器。</li></ul><h4 id="联系方式" tabindex="-1">联系方式 <a class="header-anchor" href="#联系方式" aria-label="Permalink to &quot;联系方式&quot;">​</a></h4><ul><li>Kurt Bruns 的电子邮件：kurt@solidime.com</li></ul><h4 id="会议总结" tabindex="-1">会议总结 <a class="header-anchor" href="#会议总结" aria-label="Permalink to &quot;会议总结&quot;">​</a></h4><p>本次会议讨论了如何通过存储类和 Lua 脚本优化 RADOS Gateway 对象存储，特别是在混合媒体环境下的存储效率。通过自动化的存储类分配和 Lua 脚本，成功简化了对象存储的管理，并提高了存储效率。</p>',16)])])}const p=i(r,[["render",o]]);export{g as __pageData,p as default};
